-- generated by pronto from program.cue — do not edit
SET lock_timeout = '5s';
SET statement_timeout = '60s';

BEGIN;

-- portable type domains and column predicates for PostgreSQL 18 and PostgREST 12.2.3
--
-- Regenerated whole whenever a type changes: no pronto database is deployed,
-- so a dev or CI volume is rebuilt from it. A deployed database would take a
-- changed type as a migration of its own (plugins/pronto/docs/
-- schema-change-admission.md, "Retyping a column from a domain to its base
-- type").
SET search_path = public, pg_catalog;

CREATE OR REPLACE FUNCTION public.portable_json_scalar_text(value json, expected text)
RETURNS text
LANGUAGE plpgsql IMMUTABLE STRICT PARALLEL SAFE
AS $$
BEGIN
  IF json_typeof(value) <> expected THEN
    RAISE EXCEPTION 'expected JSON %, got %', expected, json_typeof(value) USING ERRCODE = '22023';
  END IF;
  RETURN value #>> '{}';
END;
$$;

CREATE OR REPLACE FUNCTION public.portable_canonical_integer(value text, lo bigint, hi bigint)
RETURNS boolean
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
RETURN value ~ '^(0|-?[1-9][0-9]*)$' AND value::numeric >= lo AND value::numeric <= hi;

CREATE OR REPLACE FUNCTION public.portable_reject(message text)
RETURNS text
LANGUAGE plpgsql VOLATILE PARALLEL SAFE
AS $$
BEGIN
  RAISE EXCEPTION '%', message USING ERRCODE = '22023';
END;
$$;

CREATE OR REPLACE FUNCTION public.portable_double_valid(value double precision)
RETURNS boolean
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
RETURN value <> 'Infinity'::double precision
  AND value <> '-Infinity'::double precision
  AND value <> 'NaN'::double precision;

CREATE OR REPLACE FUNCTION public.portable_base64(value text)
RETURNS boolean
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
RETURN value ~ '^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$';

CREATE OR REPLACE FUNCTION public.portable_timezone_valid(value text)
RETURNS boolean
LANGUAGE sql STABLE STRICT PARALLEL SAFE
RETURN (value = 'UTC' OR value LIKE '%/%')
  AND EXISTS (SELECT 1 FROM pg_timezone_names WHERE name = value);

CREATE OR REPLACE FUNCTION public.portable_date_valid(value date)
RETURNS boolean
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
RETURN value >= date '0001-01-01' AND value < date '10000-01-01';

CREATE OR REPLACE FUNCTION public.portable_duration_valid(value interval)
RETURNS boolean
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
RETURN extract(month FROM value) = 0
  AND extract(year FROM value) = 0
  AND extract(day FROM value) = 0
  AND value >= interval '0 seconds'
  AND extract(epoch FROM value) <= 315576000000::numeric;

CREATE OR REPLACE FUNCTION public.portable_decimal_valid(value numeric, digits integer, fraction_digits integer)
RETURNS boolean
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
RETURN value = trunc(value, fraction_digits)
  AND abs(value) < power(10::numeric, digits - fraction_digits);

CREATE OR REPLACE FUNCTION public.portable_json_number_valid(value json)
RETURNS boolean
LANGUAGE plpgsql IMMUTABLE STRICT PARALLEL SAFE
AS $$
DECLARE binary64 double precision;
DECLARE source numeric;
BEGIN
  IF json_typeof(value) <> 'number' THEN RETURN false; END IF;
  BEGIN
    source := (value #>> '{}')::numeric;
    binary64 := source::double precision;
  EXCEPTION WHEN numeric_value_out_of_range OR invalid_text_representation THEN
    RETURN false;
  END;
  RETURN public.portable_double_valid(binary64) AND source = binary64::text::numeric;
END;
$$;

CREATE OR REPLACE FUNCTION public.portable_json_valid(value json)
RETURNS boolean
LANGUAGE plpgsql IMMUTABLE STRICT PARALLEL SAFE
AS $$
DECLARE item json;
BEGIN
  CASE json_typeof(value)
    WHEN 'number' THEN RETURN public.portable_json_number_valid(value);
    WHEN 'array' THEN
      FOR item IN SELECT json_array_elements(value) LOOP
        IF public.portable_json_valid(item) IS NOT TRUE THEN RETURN false; END IF;
      END LOOP;
    WHEN 'object' THEN
      IF EXISTS (SELECT entry.key FROM json_each($1) AS entry GROUP BY entry.key HAVING count(*) > 1) THEN RETURN false; END IF;
      FOR item IN SELECT entry.value FROM json_each($1) AS entry LOOP
        IF public.portable_json_valid(item) IS NOT TRUE THEN RETURN false; END IF;
      END LOOP;
    WHEN 'string' THEN
      BEGIN
        PERFORM value #>> '{}';
      EXCEPTION WHEN character_not_in_repertoire OR invalid_text_representation THEN
        RETURN false;
      END;
      RETURN true;
    WHEN 'boolean', 'null' THEN RETURN true;
    ELSE RETURN false;
  END CASE;
  RETURN true;
END;
$$;

CREATE OR REPLACE FUNCTION public.portable_shape_valid(value json, shape jsonb)
RETURNS boolean
LANGUAGE plpgsql IMMUTABLE STRICT PARALLEL SAFE
AS $$
-- A value against the shape its column's constraint states, as derive-cel
-- read it (cel-emit.ts shapeTree): the kind at each level, a record's fields
-- (none stated: open), a list's items and cap, a string's length or set, an
-- integer's range. The same walk hybrid-runtime.js makes over a step's values.
DECLARE
  kind text := shape->>'kind';
  item json;
  key text;
  n numeric;
BEGIN
  CASE kind
    WHEN 'boolean' THEN RETURN json_typeof(value) = 'boolean';
    WHEN 'string' THEN
      IF json_typeof(value) <> 'string' THEN RETURN false; END IF;
      IF shape ? 'enumValues' THEN RETURN (shape->'enumValues') ? (value #>> '{}'); END IF;
      RETURN char_length(value #>> '{}') <= (shape->>'sizeMax')::int;
    WHEN 'integer' THEN
      IF json_typeof(value) <> 'number' THEN RETURN false; END IF;
      n := (value #>> '{}')::numeric;
      IF n <> trunc(n) THEN RETURN false; END IF;
      IF shape ? 'intMin' AND n < (shape->>'intMin')::numeric THEN RETURN false; END IF;
      IF shape ? 'intMax' AND n > (shape->>'intMax')::numeric THEN RETURN false; END IF;
      RETURN true;
    WHEN 'array' THEN
      IF json_typeof(value) <> 'array' THEN RETURN false; END IF;
      IF json_array_length(value) > (shape->>'maxItems')::int THEN RETURN false; END IF;
      FOR item IN SELECT json_array_elements(value) LOOP
        IF public.portable_shape_valid(item, shape->'items') IS NOT TRUE THEN RETURN false; END IF;
      END LOOP;
      RETURN true;
    WHEN 'object' THEN
      IF json_typeof(value) <> 'object' THEN RETURN false; END IF;
      IF NOT (shape ? 'fields') THEN RETURN true; END IF;
      FOR key IN SELECT json_object_keys(value) LOOP
        IF NOT ((shape->'fields') ? key) THEN RETURN false; END IF;
      END LOOP;
      FOR key IN SELECT jsonb_object_keys(shape->'fields') LOOP
        IF value->key IS NULL THEN RETURN false; END IF;
        IF public.portable_shape_valid(value->key, shape->'fields'->key) IS NOT TRUE THEN RETURN false; END IF;
      END LOOP;
      RETURN true;
    ELSE RETURN false;
  END CASE;
END;
$$;

CREATE OR REPLACE FUNCTION public.portable_geojson_position_valid(value json)
RETURNS boolean
LANGUAGE plpgsql IMMUTABLE STRICT PARALLEL SAFE
AS $$
DECLARE longitude double precision;
DECLARE latitude double precision;
BEGIN
  IF json_typeof(value) IS DISTINCT FROM 'array' OR json_array_length(value) NOT IN (2, 3) THEN RETURN false; END IF;
  IF public.portable_json_number_valid(value -> 0) IS NOT TRUE OR public.portable_json_number_valid(value -> 1) IS NOT TRUE THEN RETURN false; END IF;
  IF json_array_length(value) = 3 AND public.portable_json_number_valid(value -> 2) IS NOT TRUE THEN RETURN false; END IF;
  longitude := (value ->> 0)::double precision;
  latitude := (value ->> 1)::double precision;
  RETURN longitude BETWEEN -180 AND 180 AND latitude BETWEEN -90 AND 90;
END;
$$;

CREATE OR REPLACE FUNCTION public.portable_geojson_positions_valid(value json, minimum integer)
RETURNS boolean
LANGUAGE plpgsql IMMUTABLE STRICT PARALLEL SAFE
AS $$
DECLARE item json;
BEGIN
  IF json_typeof(value) IS DISTINCT FROM 'array' OR json_array_length(value) < minimum THEN RETURN false; END IF;
  FOR item IN SELECT json_array_elements(value) LOOP
    IF public.portable_geojson_position_valid(item) IS NOT TRUE THEN RETURN false; END IF;
  END LOOP;
  RETURN true;
END;
$$;

CREATE OR REPLACE FUNCTION public.portable_geojson_ring_valid(value json)
RETURNS boolean
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
RETURN COALESCE(public.portable_geojson_positions_valid(value, 4)
  AND ((value -> 0 ->> 0)::numeric = (value -> (json_array_length(value) - 1) ->> 0)::numeric)
  AND ((value -> 0 ->> 1)::numeric = (value -> (json_array_length(value) - 1) ->> 1)::numeric), false);

CREATE OR REPLACE FUNCTION public.portable_geojson_geometry_valid(value json)
RETURNS boolean
LANGUAGE plpgsql IMMUTABLE STRICT PARALLEL SAFE
AS $$
DECLARE kind text;
DECLARE coordinates json;
DECLARE item json;
BEGIN
  IF json_typeof(value) IS DISTINCT FROM 'object' OR json_object_field(value, 'crs') IS NOT NULL THEN RETURN false; END IF;
  kind := value ->> 'type';
  CASE kind
    WHEN 'Point' THEN RETURN public.portable_geojson_position_valid(value -> 'coordinates');
    WHEN 'MultiPoint' THEN RETURN public.portable_geojson_positions_valid(value -> 'coordinates', 0);
    WHEN 'LineString' THEN RETURN public.portable_geojson_positions_valid(value -> 'coordinates', 2);
    WHEN 'MultiLineString' THEN
      coordinates := value -> 'coordinates';
      IF json_typeof(coordinates) IS DISTINCT FROM 'array' THEN RETURN false; END IF;
      FOR item IN SELECT json_array_elements(coordinates) LOOP
        IF public.portable_geojson_positions_valid(item, 2) IS NOT TRUE THEN RETURN false; END IF;
      END LOOP;
      RETURN true;
    WHEN 'Polygon' THEN
      coordinates := value -> 'coordinates';
      IF json_typeof(coordinates) IS DISTINCT FROM 'array' OR json_array_length(coordinates) = 0 THEN RETURN false; END IF;
      FOR item IN SELECT json_array_elements(coordinates) LOOP
        IF public.portable_geojson_ring_valid(item) IS NOT TRUE THEN RETURN false; END IF;
      END LOOP;
      RETURN true;
    WHEN 'MultiPolygon' THEN
      coordinates := value -> 'coordinates';
      IF json_typeof(coordinates) IS DISTINCT FROM 'array' THEN RETURN false; END IF;
      FOR item IN SELECT json_array_elements(coordinates) LOOP
        IF json_typeof(item) IS DISTINCT FROM 'array' OR json_array_length(item) = 0 THEN RETURN false; END IF;
        IF EXISTS (SELECT 1 FROM json_array_elements(item) AS ring WHERE public.portable_geojson_ring_valid(ring) IS NOT TRUE) THEN RETURN false; END IF;
      END LOOP;
      RETURN true;
    WHEN 'GeometryCollection' THEN
      coordinates := value -> 'geometries';
      IF json_typeof(coordinates) IS DISTINCT FROM 'array' THEN RETURN false; END IF;
      FOR item IN SELECT json_array_elements(coordinates) LOOP
        IF public.portable_geojson_geometry_valid(item) IS NOT TRUE THEN RETURN false; END IF;
      END LOOP;
      RETURN true;
    ELSE RETURN false;
  END CASE;
END;
$$;

CREATE OR REPLACE FUNCTION public.portable_geojson_object_valid(value json)
RETURNS boolean
LANGUAGE plpgsql IMMUTABLE STRICT PARALLEL SAFE
AS $$
DECLARE item json;
DECLARE properties json;
BEGIN
  IF json_typeof(value) IS DISTINCT FROM 'object' THEN RETURN false; END IF;
  CASE value ->> 'type'
    WHEN 'Feature' THEN
      properties := value -> 'properties';
      RETURN json_object_field(value, 'geometry') IS NOT NULL
        AND json_object_field(value, 'properties') IS NOT NULL
        AND json_typeof(properties) IN ('object', 'null')
        AND (json_typeof(value -> 'geometry') = 'null' OR public.portable_geojson_geometry_valid(value -> 'geometry') IS TRUE);
    WHEN 'FeatureCollection' THEN
      IF json_object_field(value, 'features') IS NULL OR json_typeof(value -> 'features') IS DISTINCT FROM 'array' THEN RETURN false; END IF;
      FOR item IN SELECT json_array_elements(value -> 'features') LOOP
        IF public.portable_geojson_object_valid(item) IS NOT TRUE OR item ->> 'type' IS DISTINCT FROM 'Feature' THEN RETURN false; END IF;
      END LOOP;
      RETURN true;
    ELSE RETURN public.portable_geojson_geometry_valid(value);
  END CASE;
END;
$$;

CREATE OR REPLACE FUNCTION public.portable_geojson_valid(value json)
RETURNS boolean
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
RETURN public.portable_json_valid(value) AND public.portable_geojson_object_valid(value);

CREATE DOMAIN public.portable_int64 AS bigint CHECK (VALUE IS NULL OR COALESCE((true), false));
CREATE DOMAIN public.portable_bytes AS bytea CHECK (VALUE IS NULL OR COALESCE((true), false));
CREATE DOMAIN public.portable_timestamp AS timestamptz CHECK (VALUE IS NULL OR COALESCE((VALUE >= timestamptz '0001-01-01 00:00:00+00' AND VALUE < timestamptz '10000-01-01 00:00:00+00'), false));
CREATE DOMAIN public.portable_time AS time(6) CHECK (VALUE IS NULL OR COALESCE((VALUE < time '24:00:00'), false));
CREATE DOMAIN public.portable_duration AS interval CHECK (VALUE IS NULL OR COALESCE((public.portable_duration_valid(VALUE)), false));


CREATE OR REPLACE FUNCTION public.portable_int64_from_json(value json)
RETURNS public.portable_int64
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
RETURN CASE WHEN public.portable_canonical_integer(public.portable_json_scalar_text(value, 'string'), -9223372036854775808, 9223372036854775807) THEN public.portable_json_scalar_text(value, 'string')::bigint ELSE public.portable_reject('portable_int64 must be a canonical JSON string')::bigint END::public.portable_int64;

CREATE OR REPLACE FUNCTION public.portable_int64_from_text(value text)
RETURNS public.portable_int64
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
RETURN CASE WHEN public.portable_canonical_integer(value, -9223372036854775808, 9223372036854775807) THEN value::bigint ELSE public.portable_reject('portable_int64 must be canonical')::bigint END::public.portable_int64;

CREATE OR REPLACE FUNCTION public.portable_int64_to_json(value public.portable_int64)
RETURNS json
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
RETURN to_json(value::text);

CREATE CAST (json AS public.portable_int64) WITH FUNCTION public.portable_int64_from_json(json) AS IMPLICIT;
CREATE CAST (text AS public.portable_int64) WITH FUNCTION public.portable_int64_from_text(text) AS IMPLICIT;
CREATE CAST (public.portable_int64 AS json) WITH FUNCTION public.portable_int64_to_json(public.portable_int64) AS IMPLICIT;

CREATE OR REPLACE FUNCTION public.portable_bytes_from_json(value json)
RETURNS public.portable_bytes
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
RETURN CASE WHEN public.portable_base64(public.portable_json_scalar_text(value, 'string')) THEN decode(public.portable_json_scalar_text(value, 'string'), 'base64') ELSE public.portable_reject('portable_bytes must be strict base64')::bytea END::public.portable_bytes;

CREATE OR REPLACE FUNCTION public.portable_bytes_from_text(value text)
RETURNS public.portable_bytes
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
RETURN CASE WHEN public.portable_base64(value) THEN decode(value, 'base64') ELSE public.portable_reject('portable_bytes must be strict base64')::bytea END::public.portable_bytes;

CREATE OR REPLACE FUNCTION public.portable_bytes_to_json(value public.portable_bytes)
RETURNS json
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
RETURN to_json(replace(encode(value::bytea, 'base64'), E'\n', ''));

CREATE CAST (json AS public.portable_bytes) WITH FUNCTION public.portable_bytes_from_json(json) AS IMPLICIT;
CREATE CAST (text AS public.portable_bytes) WITH FUNCTION public.portable_bytes_from_text(text) AS IMPLICIT;
CREATE CAST (public.portable_bytes AS json) WITH FUNCTION public.portable_bytes_to_json(public.portable_bytes) AS IMPLICIT;

CREATE OR REPLACE FUNCTION public.portable_timestamp_from_json(value json)
RETURNS public.portable_timestamp
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
RETURN CASE WHEN public.portable_json_scalar_text(value, 'string') ~ '^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])T([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9]\.[0-9]{6}Z$' THEN public.portable_json_scalar_text(value, 'string')::timestamptz ELSE public.portable_reject('portable_timestamp must be UTC with exactly six fractional digits')::timestamptz END::public.portable_timestamp;

CREATE OR REPLACE FUNCTION public.portable_timestamp_from_text(value text)
RETURNS public.portable_timestamp
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
RETURN CASE WHEN value ~ '^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])T([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9]\.[0-9]{6}Z$' THEN value::timestamptz ELSE public.portable_reject('portable_timestamp must be UTC with exactly six fractional digits')::timestamptz END::public.portable_timestamp;

CREATE OR REPLACE FUNCTION public.portable_timestamp_to_json(value public.portable_timestamp)
RETURNS json
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
RETURN to_json(to_char(value::timestamptz AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));

CREATE CAST (json AS public.portable_timestamp) WITH FUNCTION public.portable_timestamp_from_json(json) AS IMPLICIT;
CREATE CAST (text AS public.portable_timestamp) WITH FUNCTION public.portable_timestamp_from_text(text) AS IMPLICIT;
CREATE CAST (public.portable_timestamp AS json) WITH FUNCTION public.portable_timestamp_to_json(public.portable_timestamp) AS IMPLICIT;

CREATE OR REPLACE FUNCTION public.portable_time_from_json(value json)
RETURNS public.portable_time
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
RETURN CASE WHEN public.portable_json_scalar_text(value, 'string') ~ '^[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{6}$' AND public.portable_json_scalar_text(value, 'string') < '24:00:00.000000' THEN public.portable_json_scalar_text(value, 'string')::time ELSE public.portable_reject('portable_time must be HH:mm:ss.ffffff before 24:00')::time END::public.portable_time;

CREATE OR REPLACE FUNCTION public.portable_time_from_text(value text)
RETURNS public.portable_time
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
RETURN CASE WHEN value ~ '^[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{6}$' AND value < '24:00:00.000000' THEN value::time ELSE public.portable_reject('portable_time must be HH:mm:ss.ffffff before 24:00')::time END::public.portable_time;

CREATE OR REPLACE FUNCTION public.portable_time_to_json(value public.portable_time)
RETURNS json
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
RETURN to_json(to_char(value::time, 'HH24:MI:SS.US'));

CREATE CAST (json AS public.portable_time) WITH FUNCTION public.portable_time_from_json(json) AS IMPLICIT;
CREATE CAST (text AS public.portable_time) WITH FUNCTION public.portable_time_from_text(text) AS IMPLICIT;
CREATE CAST (public.portable_time AS json) WITH FUNCTION public.portable_time_to_json(public.portable_time) AS IMPLICIT;

CREATE OR REPLACE FUNCTION public.portable_duration_from_json(value json)
RETURNS public.portable_duration
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
RETURN CASE WHEN public.portable_json_scalar_text(value, 'string') ~ '^PT(0|[1-9][0-9]*)(\.[0-9]{0,5}[1-9])?S$' THEN (substring(public.portable_json_scalar_text(value, 'string') FROM 3 FOR char_length(public.portable_json_scalar_text(value, 'string')) - 3) || ' seconds')::interval ELSE public.portable_reject('portable_duration must be canonical total seconds at microsecond precision')::interval END::public.portable_duration;

CREATE OR REPLACE FUNCTION public.portable_duration_from_text(value text)
RETURNS public.portable_duration
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
RETURN CASE WHEN value ~ '^PT(0|[1-9][0-9]*)(\.[0-9]{0,5}[1-9])?S$' THEN (substring(value FROM 3 FOR char_length(value) - 3) || ' seconds')::interval ELSE public.portable_reject('portable_duration must be canonical total seconds at microsecond precision')::interval END::public.portable_duration;

CREATE OR REPLACE FUNCTION public.portable_duration_to_json(value public.portable_duration)
RETURNS json
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
RETURN to_json('PT' || trim_scale(extract(epoch FROM value::interval))::text || 'S');

CREATE CAST (json AS public.portable_duration) WITH FUNCTION public.portable_duration_from_json(json) AS IMPLICIT;
CREATE CAST (text AS public.portable_duration) WITH FUNCTION public.portable_duration_from_text(text) AS IMPLICIT;
CREATE CAST (public.portable_duration AS json) WITH FUNCTION public.portable_duration_to_json(public.portable_duration) AS IMPLICIT;


COMMIT;
